Fringe** fringe = fringes;
int count = sizeof(fringes) / sizeof(fringes[0]);
do {
    Fringe* object = *fringe;
    if (object != 0 && (object->list_flags & BOD_FLAG_LINKED) != 0)
        g_game->active_bod_list.remove_bod(object);
    fringe++;
    count--;
} while (count != 0);

